SELECT n.*, u.name as university_name
FROM news n
LEFT JOIN university u ON n.university_id = u.id


        AND n.title LIKE CONCAT('%', #{title}, '%')


        AND n.type = #{type}


        AND n.status = #{status}


        AND n.university_id = #{universityId}


        AND n.category_id = #{categoryId}


ORDER BY n.created_at DESC
